CATALOG = {o['key']: o for o in OPTIONS + ARGS}


def catalog(vendors) -> list:
    """Options for one vendor or several (a mixed layer split spans cards of different vendors).
    Vendor-specific first (in the order given), then common options; no key twice."""
    vs = [vendors] if isinstance(vendors, str) else list(vendors)
    vs = [v for v in vs if v in VENDORS] or ['all']
    out, seen = [], set()
    for v in vs + ['all']:
        for o in OPTIONS + ARGS:
            if o['vendor'] == v and o['key'] not in seen:
                seen.add(o['key'])
                out.append(dict(o))
    return out


def detect_vendor(cfg: dict) -> str:
    """nvidia|amd|intel|apple|all from the run config's backend key (cuda/hip/sycl/metal); 'all' when unknown."""
    b = (cfg.get('backend') or '').lower()
    return {'hip': 'amd', 'cuda': 'nvidia', 'sycl': 'intel', 'metal': 'apple'}.get(b, 'all')


def detect_archs(log_path) -> list:
    """Every architecture in the engine's startup lines, in order: ['sm_89', 'gfx1201'] for a mixed layer split.
    Scans the last 4 MiB (seek, not a whole-file read: serving logs run to hundreds of MB)."""
    try:
        with open(log_path, 'rb') as f:
            f.seek(max(0, f.seek(0, 2) - 4194304))
            tail = f.read().decode('utf-8', 'replace')
    except OSError:
        return []
    matches = []
    for rx in (r'gfx\d{3,4}', r'sm_\d{2,3}', r'compute capability (\d{1,2})\.(\d)',
               r'\b(Arc \w+|A770|A750)\b', r'\bApple M\d+(?: Pro| Max| Ultra)?\b'):
        for m in re.finditer(rx, tail):
            value = 'sm_' + m.group(1) + m.group(2) if m.lastindex == 2 else m.group(0)
            matches.append((m.start(), value))
    out = []
    for _, value in sorted(matches):
        if value not in out:
            out.append(value)
    return out


def detect_arch(log_path) -> str:
    """The LAST architecture the engine reported: a long-running log's newest start is at its end; '' when none."""
    archs = detect_archs(log_path)
    return archs[-1] if archs else ''


def detect_vendors(cfg: dict, log_path=None) -> list:
    """Vendors the engine runs on: the backend key first, plus every vendor the engine's startup lines report
    (a layer split can span cards of different vendors); ['all'] when nothing is known."""
    b = (cfg.get('backend') or '').lower()
    out = [{'hip': 'amd', 'cuda': 'nvidia', 'sycl': 'intel', 'metal': 'apple'}.get(b, '')]
    out = [v for v in out if v]
    for arch in detect_archs(log_path) if log_path else []:
        v = vendor_of_arch(arch)
        if v and v not in out:
            out.append(v)
    return out or ['all']


def vendor_of_arch(arch: str) -> str:
    if arch.startswith('gfx'): return 'amd'
    if arch.startswith('sm_'): return 'nvidia'
    if arch.startswith('Apple M'): return 'apple'
    return 'intel' if arch else ''

